/**
 * Shared tool-chip pending lifetime for defaults and agentic delivery.
 * Always consume on `actions.requested`. Skip the paint when tools are
 * off or the batch is empty.
 */
import { truncateTypingStatus } from "./api.js";
import { firstNonEmptyLine } from "./assistant.js";
export function rememberPendingToolCall(state, finishReason, text) {
    if (finishReason === "tool_call") {
        state.pendingToolCallMessage = firstNonEmptyLine(text) ?? null;
        return;
    }
    state.pendingToolCallMessage = null;
}
export function takeToolChipLine(state, tools, calls) {
    const pending = state.pendingToolCallMessage;
    state.pendingToolCallMessage = null;
    if (tools === false || calls.length === 0) {
        return undefined;
    }
    return pending !== null ? truncateTypingStatus(pending) : truncateTypingStatus(tools(calls));
}
